//! Retention sweeps for nullable blob-pointer columns.
//!
//! Several rows carry a nullable blob pointer, with its own retention expiry,
//! whose bytes are released while the row itself is kept: a document's bytes, a
//! detection's enrichment intermediate and its base-analysis (audit) findings, and
//! a redaction's review-analysis findings. Each is released the same way — find
//! the rows whose expiry for that pointer has passed, null the pointer, and drop
//! the reference so the blob reaper can purge the bytes.
//!
//! That one shape is generated by [`clear_expired_blob_pointer`] for each
//! `(table, column)`, so the concurrency-safe null-then-guarded-decrement is
//! written once rather than copied per column.

use diesel::dsl::now;
use diesel::prelude::*;
use diesel_async::{AsyncConnection, RunQueryDsl};
use uuid::Uuid;

use crate::query::WorkspaceBlobRepository;
use crate::{PgConnection, Result};

/// Generates a `clear_expired_*` sweep for one nullable blob-pointer column.
///
/// The generated function reclaims up to `limit` rows whose expiry for the
/// pointer has passed: it nulls the pointer (keeping the row) and drops
/// the blob reference, so the reaper's purge sweep can then reclaim the bytes once
/// nothing else references them.
/// Rows are locked `FOR UPDATE SKIP LOCKED`, the pointer is nulled only while it
/// still holds the selected blob, and the reference is dropped only when the null
/// actually took — so a concurrent sweep never double-drops. Returns how many were
/// cleared. Runs in one transaction so the null and the drop commit together.
///
/// `expiring_on` names the row's own expiry column for that pointer: retention
/// lives on the referrer, since identical bytes share one blob across referrers
/// with different retention. An optional `keep_while` guard is a condition on
/// `$table`: a row it matches keeps its pointer even past its window. It is
/// checked both when selecting and again when clearing, since a guarded fact (a
/// detection starting on a document) can commit between the two.
macro_rules! clear_expired_blob_pointer {
    (
        $(#[$meta:meta])* $vis:vis fn $name:ident on $table:ident . $column:ident,
        expiring_on $expiry:path
        $(, keep_while $guard:expr)?
    ) => {
        $(#[$meta])*
        ///
        /// # Errors
        ///
        /// A database error if the sweep or a reference drop fails.
        $vis async fn $name(conn: &mut PgConnection, limit: i64) -> Result<usize> {
            use crate::schema::{workspace_blobs, $table};

            conn.transaction(async |conn| {
                let expired: Vec<(Uuid, Uuid)> = $table::table
                    .inner_join(
                        workspace_blobs::table
                            .on($table::$column.eq(workspace_blobs::id.nullable())),
                    )
                    .filter($expiry.is_not_null())
                    .filter($expiry.lt(now))
                    .filter(workspace_blobs::purged_at.is_null())
                    $(.filter(diesel::dsl::not($guard)))?
                    .limit(limit)
                    .select(($table::id, workspace_blobs::id))
                    .for_update()
                    .skip_locked()
                    .load(conn)
                    .await?;

                let mut dropped = 0usize;
                for (row_id, blob_id) in &expired {
                    // The guard is checked again here: the selection's snapshot
                    // predates its row locks, so a row it guards can have changed
                    // in between, and this statement sees what has committed since.
                    let cleared = diesel::update(
                        $table::table
                            .filter($table::id.eq(row_id))
                            .filter($table::$column.eq(blob_id))
                            $(.filter(diesel::dsl::not($guard)))?,
                    )
                    .set($table::$column.eq(None::<Uuid>))
                    .execute(conn)
                    .await?;
                    if cleared == 1 {
                        conn.decrement_ref(*blob_id).await?;
                        dropped += 1;
                    }
                }

                Ok(dropped)
            })
            .await
        }
    };
}

clear_expired_blob_pointer! {
    /// Reclaims live documents' expired bytes (originals and redacted outputs).
    ///
    /// A deleted document is skipped: deleting it already dropped its reference.
    /// A document with a detection still pending or executing keeps its bytes
    /// until that detection settles, so analysis never loses its input.
    pub fn clear_expired_document_blobs on workspace_documents.blob_id,
    expiring_on crate::schema::workspace_documents::expires_at,
    keep_while crate::schema::workspace_documents::deleted_at
        .is_not_null()
        .or(diesel::dsl::exists(
            crate::schema::workspace_detections::table
                .filter(
                    crate::schema::workspace_detections::input_document_id
                        .eq(crate::schema::workspace_documents::id),
                )
                .filter(
                    crate::schema::workspace_detections::status
                        .eq_any(crate::types::DetectionStatus::IN_PROGRESS),
                ),
        ))
}

clear_expired_blob_pointer! {
    /// Reclaims detections' expired enrichment-intermediate bytes.
    pub fn clear_expired_detection_intermediates on workspace_detections.intermediate_blob_id,
    expiring_on crate::schema::workspace_detections::intermediate_expires_at
}

clear_expired_blob_pointer! {
    /// Reclaims detections' expired base-analysis (audit) bytes.
    pub fn clear_expired_detection_audits on workspace_detections.audit_blob_id,
    expiring_on crate::schema::workspace_detections::audit_expires_at
}

clear_expired_blob_pointer! {
    /// Reclaims redactions' expired review-analysis bytes.
    pub fn clear_expired_review_audits on workspace_redactions.review_audit_blob_id,
    expiring_on crate::schema::workspace_redactions::review_audit_expires_at
}

#[cfg(test)]
mod tests {
    use jiff::{Span, Timestamp};

    use super::*;
    use crate::PgConn;
    use crate::model::{NewBlob, NewWorkspaceDetection, NewWorkspaceRedaction, WorkspaceDocument};
    use crate::query::{
        WorkspaceBlobRepository, WorkspaceDetectionRepository, WorkspaceDocumentRepository,
        WorkspaceRedactionRepository,
    };
    use crate::test_util::{TestDatabase, backdate};
    use crate::types::{DetectionStatus, Retention};

    /// Loads a live document by id, unscoped (tests only).
    async fn document(
        conn: &mut PgConn,
        document_id: Uuid,
    ) -> anyhow::Result<Option<WorkspaceDocument>> {
        use crate::schema::workspace_documents::dsl;

        Ok(dsl::workspace_documents
            .filter(dsl::id.eq(document_id))
            .filter(dsl::deleted_at.is_null())
            .select(WorkspaceDocument::as_select())
            .first(conn)
            .await
            .optional()?)
    }

    /// Moves a document to a default-retention window that began `hours_ago`,
    /// returning its blob's id.
    async fn age_document_blob(
        conn: &mut PgConn,
        document_id: Uuid,
        hours_ago: i64,
    ) -> anyhow::Result<Uuid> {
        let blob_id = document(conn, document_id)
            .await?
            .and_then(|document| document.blob_id)
            .expect("seeded document has bytes");
        let written = Timestamp::now() - Span::new().hours(hours_ago);
        backdate::document_expiry(conn, document_id, Retention::default().expires_at(written))
            .await?;
        Ok(blob_id)
    }

    /// An hour ago: a window that has just passed.
    fn an_hour_ago() -> Timestamp {
        Timestamp::now() - Span::new().hours(1)
    }

    #[tokio::test]
    async fn clearing_a_detection_audit_keeps_the_row_and_nulls_the_pointer() -> anyhow::Result<()>
    {
        use crate::schema::workspace_detections::{self, dsl};

        let db = TestDatabase::start().await;
        let seeded = db.seed_document().await;
        let mut conn = db.client.get_connection().await?;

        let detection = conn
            .create_workspace_detection(NewWorkspaceDetection::test(
                seeded.workspace_id,
                seeded.account_id,
                seeded.document_id,
            ))
            .await?;

        // Attach a base-analysis blob (records the reference), then point the
        // detection at it — mirroring what finalize does.
        let blob = conn
            .find_or_create_blob(NewBlob::test(seeded.workspace_id))
            .await?;
        diesel::update(workspace_detections::table.filter(dsl::id.eq(detection.id)))
            .set(dsl::audit_blob_id.eq(Some(blob.id)))
            .execute(&mut conn)
            .await?;
        backdate::detection_audit_expiry(&mut conn, detection.id, an_hour_ago()).await?;

        let cleared = clear_expired_detection_audits(&mut conn, 50).await?;
        assert_eq!(cleared, 1);

        // The detection row survives (a ledger record); its pointer is nulled and
        // the blob reference dropped so the reaper can reclaim the bytes.
        let kept = conn
            .find_workspace_detection_by_id(seeded.workspace_id, detection.id)
            .await?
            .expect("detection row survives");
        assert!(kept.audit_blob_id.is_none(), "the audit pointer is nulled");
        assert_eq!(conn.find_blob_by_id(blob.id).await?.unwrap().ref_count, 0);
        Ok(())
    }

    #[tokio::test]
    async fn clearing_a_review_audit_keeps_the_row_and_nulls_the_pointer() -> anyhow::Result<()> {
        let db = TestDatabase::start().await;
        let seeded = db.seed_document().await;
        let mut conn = db.client.get_connection().await?;

        let detection = conn
            .create_workspace_detection(NewWorkspaceDetection::test(
                seeded.workspace_id,
                seeded.account_id,
                seeded.document_id,
            ))
            .await?;
        let blob = conn
            .find_or_create_blob(NewBlob::test(seeded.workspace_id))
            .await?;
        let redaction = conn
            .create_redaction(NewWorkspaceRedaction {
                review_audit_blob_id: Some(blob.id),
                review_audit_expires_at: Some(an_hour_ago().into()),
                ..NewWorkspaceRedaction::test(detection.id, seeded.account_id)
            })
            .await?;

        let cleared = clear_expired_review_audits(&mut conn, 50).await?;
        assert_eq!(cleared, 1);

        let kept = conn
            .find_redaction_in_workspace(seeded.workspace_id, redaction.id)
            .await?
            .expect("redaction row survives");
        assert!(
            kept.review_audit_blob_id.is_none(),
            "the review-audit pointer is nulled"
        );
        assert_eq!(conn.find_blob_by_id(blob.id).await?.unwrap().ref_count, 0);
        Ok(())
    }

    /// A document uploaded under the default (ephemeral) retention keeps its bytes
    /// through the processing window, and while a detection on it is in progress,
    /// then is released so the reaper purges the bytes.
    #[tokio::test]
    async fn an_ephemeral_document_is_released_after_its_window() -> anyhow::Result<()> {
        use crate::schema::workspace_detections::{self, dsl};

        let db = TestDatabase::start().await;
        let seeded = db.seed_document().await;
        let mut conn = db.client.get_connection().await?;

        // Inside the window: nothing is released.
        age_document_blob(&mut conn, seeded.document_id, 1).await?;
        assert_eq!(clear_expired_document_blobs(&mut conn, 50).await?, 0);

        // Past the window, but a detection is still pending: kept.
        let blob_id = age_document_blob(&mut conn, seeded.document_id, 25).await?;
        let detection = conn
            .create_workspace_detection(NewWorkspaceDetection::test(
                seeded.workspace_id,
                seeded.account_id,
                seeded.document_id,
            ))
            .await?;
        assert_eq!(clear_expired_document_blobs(&mut conn, 50).await?, 0);

        // Once the detection settles, the bytes are released and due for purge.
        diesel::update(workspace_detections::table.filter(dsl::id.eq(detection.id)))
            .set(dsl::status.eq(DetectionStatus::Complete))
            .execute(&mut conn)
            .await?;
        assert_eq!(clear_expired_document_blobs(&mut conn, 50).await?, 1);

        let document = document(&mut conn, seeded.document_id)
            .await?
            .expect("the document row survives");
        assert!(document.blob_id.is_none(), "the bytes pointer is nulled");
        let due = conn.blobs_due_for_purge(50).await?;
        assert!(
            due.iter().any(|blob| blob.id == blob_id),
            "the bytes are due for purge"
        );
        Ok(())
    }

    /// Deleting a document already dropped its reference, so the sweep must not
    /// drop it again: on a deduplicated blob that would steal a live referrer's.
    #[tokio::test]
    async fn a_deleted_document_is_not_released_twice() -> anyhow::Result<()> {
        let db = TestDatabase::start().await;
        let seeded = db.seed_document().await;
        let mut conn = db.client.get_connection().await?;

        let blob_id = age_document_blob(&mut conn, seeded.document_id, 25).await?;
        // A second live referrer of the same bytes.
        {
            use crate::schema::workspace_blobs::dsl;

            diesel::update(dsl::workspace_blobs.filter(dsl::id.eq(blob_id)))
                .set(dsl::ref_count.eq(dsl::ref_count + 1))
                .execute(&mut conn)
                .await?;
        }
        conn.delete_workspace_document(seeded.document_id).await?;
        assert_eq!(conn.find_blob_by_id(blob_id).await?.unwrap().ref_count, 1);

        assert_eq!(clear_expired_document_blobs(&mut conn, 50).await?, 0);
        assert_eq!(conn.find_blob_by_id(blob_id).await?.unwrap().ref_count, 1);
        Ok(())
    }

    /// Identical files share one blob, but each document keeps its own window:
    /// re-uploading a file near the end of the first copy's window does not cut
    /// the second copy's window short, and the bytes are purged only once both
    /// are released.
    #[tokio::test]
    async fn identical_documents_each_keep_their_own_window() -> anyhow::Result<()> {
        use crate::model::NewWorkspaceDocument;

        let db = TestDatabase::start().await;
        let seeded = db.seed_document().await;
        let mut conn = db.client.get_connection().await?;

        // The first copy's window has passed; a second copy of the same bytes was
        // uploaded an hour ago, so its window is still open.
        let blob_id = age_document_blob(&mut conn, seeded.document_id, 25).await?;
        let first_blob = conn.find_blob_by_id(blob_id).await?.expect("first blob");
        let second_blob = NewBlob {
            content_hash: first_blob.content_hash,
            file_size_bytes: first_blob.file_size_bytes,
            storage_bucket: first_blob.storage_bucket,
            ..NewBlob::test(seeded.workspace_id)
        };
        let second = conn
            .create_workspace_document(
                NewWorkspaceDocument {
                    expires_at: Some(Retention::default().expires_at(Timestamp::now()).into()),
                    ..NewWorkspaceDocument::test(
                        seeded.workspace_id,
                        seeded.account_id,
                        Uuid::nil(),
                    )
                },
                second_blob,
            )
            .await?;
        assert_eq!(
            second.blob_id,
            Some(blob_id),
            "identical bytes share a blob"
        );

        // Only the first copy is released; the bytes stay for the second.
        assert_eq!(clear_expired_document_blobs(&mut conn, 50).await?, 1);
        let kept = document(&mut conn, second.id)
            .await?
            .expect("second copy survives");
        assert_eq!(kept.blob_id, Some(blob_id));
        assert_eq!(conn.find_blob_by_id(blob_id).await?.unwrap().ref_count, 1);
        let due = conn.blobs_due_for_purge(50).await?;
        assert!(
            due.iter().all(|blob| blob.id != blob_id),
            "still referenced"
        );
        Ok(())
    }
}
